#include <iostream>
#include <vector>
#include <cassert>

using namespace std;

#define FOR(i, a, b) for (int i = (a); i < (b); ++i)
#define REP(i, n) FOR(i, 0, n)

typedef long long llint;

const int MOD = 1000000007;

int add(int a, int b) {
    return (a + b) >= MOD ? (a + b - MOD) : (a + b);
}

int mul(int a, int b) {
    return (llint(a) * b) % MOD;
}

const int SIZE = 32;

struct Matrix {
    int mat[SIZE][SIZE];
    Matrix() { for (int i = 0; i < SIZE; ++i) for (int j = 0; j < SIZE; ++j) mat[i][j] = 0; }
    int* operator[](int i) { return mat[i]; }
    friend Matrix operator*(const Matrix& a, const Matrix& b) {
        Matrix res;
        for (int i = 0; i < SIZE; ++i)
            for (int j = 0; j < SIZE; ++j)
                for (int k = 0; k < SIZE; ++k)
                    res[i][j] = add(res[i][j], mul(a[i][k], b[k][j]));
        return res;
    }
};

const int MAX_D = 64;
const int MAX_K = 32;

Matrix f[MAX_D];
int k;

Matrix build_matrix(int n, int offset) {
    Matrix result;
    for (int i = 0; i <= k; ++i)
        for (int j = 0; j <= k; ++j) {
            int ni = (i == k) ? i : (i + offset) % k;
            int nj = (j == k) ? j : (j + offset) % k;
            result[ni][nj] = f[n][i][j];
        }
    return result;
}

int sum_digits(llint n) {
    int total = 0;
    while (n > 0) {
        total += n % k;
        n /= k;
    }
    return total % k;
}

int main() {
    llint n;
    int base;
    cin >> n >> base;
    k = base;

    int digit_count = 0;
    llint temp = n;
    while (temp > 0) {
        temp /= k;
        ++digit_count;
    }

    Matrix identity;
    for (int i = 0; i <= k; ++i) identity[i][i] = 1;

    f[0] = identity;
    for (int i = 0; i <= k; ++i) f[0][i][0] = 1;

    for (int i = 1; i < digit_count; ++i) {
        f[i] = identity;
        for (int j = 0; j < k; ++j)
            f[i] = f[i] * build_matrix(i - 1, j);
    }

    llint current = 0;
    llint power = 1;

    --digit_count;
    for (int i = 0; i < digit_count; ++i) power *= k;

    Matrix answer = identity;
    while (current < n) {
        assert(digit_count >= 0);
        while (current + power <= n) {
            answer = answer * build_matrix(digit_count, sum_digits(current));
            current += power;
        }
        power /= k;
        --digit_count;
    }

    int total_sum = 0;
    for (int i = 0; i <= k; ++i)
        total_sum = add(total_sum, answer[k][i]);
    cout << total_sum << "\n";
    return 0;
}
